import * as THREE from '../three.module.js';
// Merge only rigid parts sharing a material; never merge animated bones.
export function batchRigidMeshes(root){root.updateMatrixWorld(true);const inverse=root.matrixWorld.clone().invert(),groups=new Map();root.traverse(o=>{if(o.isMesh&&!o.isInstancedMesh){if(!groups.has(o.material))groups.set(o.material,[]);groups.get(o.material).push(o);}});for(const [material,list] of groups){if(list.length<2)continue;const positions=[],normals=[],uv=[],indices=[];let offset=0;for(const mesh of list){const g=mesh.geometry.clone().applyMatrix4(inverse.clone().multiply(mesh.matrixWorld)),p=g.attributes.position,n=g.attributes.normal,t=g.attributes.uv;for(let i=0;i<p.count;i++){positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));uv.push(t?.getX(i)||0,t?.getY(i)||0);}for(let i=0;i<(g.index?.count||p.count);i++)indices.push(offset+(g.index?g.index.getX(i):i));offset+=p.count;mesh.parent.remove(mesh);g.dispose();}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(indices);const mesh=new THREE.Mesh(g,material);mesh.castShadow=true;mesh.receiveShadow=true;root.add(mesh);}}
